import pyomo.environ as pyo

DATA = {
    "budget": 10000,
    "min_X": 2000,
    "min_Y": 3000,
    "cost": {"X": 0.02, "Y": 0.03},
    "options": ["X", "Y"],
    "min_alloc": {"X": 2000, "Y": 3000},
    "max_alloc": {"X": 10000, "Y": 10000},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.OPTIONS = pyo.Set(initialize=d["options"])

    def alloc_bounds(m, i):
        return (d["min_alloc"][i], d["max_alloc"][i])

    model.alloc = pyo.Var(
        model.OPTIONS,
        within=pyo.NonNegativeIntegers,
        bounds=alloc_bounds,
    )

    def obj_rule(m):
        return sum(d["cost"][i] * m.alloc[i] for i in m.OPTIONS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def budget_rule(m):
        return sum(m.alloc[i] for i in m.OPTIONS) <= d["budget"]

    model.budget = pyo.Constraint(rule=budget_rule)

    def min_x_rule(m):
        return m.alloc["X"] >= d["min_X"]

    model.min_x = pyo.Constraint(rule=min_x_rule)

    def min_y_rule(m):
        return m.alloc["Y"] >= d["min_Y"]

    model.min_y = pyo.Constraint(rule=min_y_rule)

    return model


